export const bikenArtikelIds = ['biken/zwischen-orten', 'biken/mit-kindern', 'biken/e-bike'];

export function bikenLocale(locale: Locale): FamilieText | null {
  if (locale === 'de') return null;
  return uebersicht[locale];
}

export function bikenArtikel(locale: Locale, id: string): ArtikelText | null {
  if (locale === 'de') return null;
  return artikel[locale][id] ?? null;
}
